import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import "bootstrap/dist/css/bootstrap.min.css";
import "../assets/css/light-bootstrap-dashboard-react.css?v=2.0.0";

import {
  Container,
  Row,
  Col,
  Card,
} from "react-bootstrap";

function Dashboard() {
  const [chartData, setChartData] = useState({
    labels: [],
    series: []
  });

  const fetchData = async () => {
    try {
      // ดึงข้อมูลจาก Backend (อย่าลืมรัน node js/server.js นะครับ)
      const response = await fetch('http://localhost:3001/api/chart-data');
      const result = await response.json();

      console.log("Data from DB:", result); // ดูค่าใน Console (F12)

      if (result && result.series) {
        setChartData(result);
      }
    } catch (error) {
      console.error("Error fetching data:", error);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, []);

  // --- ตั้งค่ากราฟ (จุดที่แก้ Error) ---
  const options = {
    lineSmooth: true, // <--- แก้จาก Chartist.Interpolation... เป็น true (ใช้ค่าเริ่มต้น สวยเหมือนกัน)
    low: 0,
    high: 30, // ปรับความสูงแกน Y ตรงนี้ (ถ้าคนเยอะให้เพิ่มเลขนี้)
    showArea: false,
    height: "245px",
    axisX: {
      showGrid: false,
    },
    showLine: true,
    showPoint: true,
    fullWidth: true,
    chartPadding: {
      right: 50
    }
  };

  const responsiveOptions = [
    [
      "screen and (max-width: 640px)",
      {
        axisX: {
          labelInterpolationFnc: function (value) {
            return value[0];
          },
        },
      },
    ],
  ];

  return (
    <>
      <Container fluid>
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">Passenger Density</Card.Title>
                <p className="card-category">ข้อมูลจำนวนคนแต่ละช่วงเวลา</p>
              </Card.Header>
              <Card.Body>
                <div className="ct-chart" id="chartHours">
                  {/* เช็คว่ามีข้อมูลไหม ถ้าไม่มีให้ขึ้น Loading */}
                  {chartData.series.length > 0 ? (
                    <ChartistGraph
                      data={chartData}
                      type="Line"
                      options={options}
                      responsiveOptions={responsiveOptions}
                    />
                  ) : (
                    <div style={{textAlign: 'center', padding: '20px'}}>
                        <p>... รอข้อมูลจาก Database ...</p>
                        <small>(ตรวจสอบว่าเปิด Backend หรือยัง?)</small>
                    </div>
                  )}
                </div>
              </Card.Body>
              <Card.Footer>
                <div className="legend">
                  <i className="fas fa-circle text-info"></i> วิศวะ (ฟ้า) &nbsp;
                  <i className="fas fa-circle text-danger"></i> วิทยา (แดง) &nbsp;
                  <i className="fas fa-circle text-warning"></i> ศิลปศาสตร์ (ส้ม) &nbsp;
                  <i className="fas fa-circle" style={{color: '#9368E9'}}></i> PKY (ม่วง)
                </div>
                <hr />
                <div className="stats">
                  <i className="fas fa-history"></i> อัปเดตล่าสุดเมื่อสักครู่
                </div>
              </Card.Footer>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
}

export default Dashboard;
